{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C23"],
      "claim": "Pethidine, a phenylpiperidine ester with a basic tertiary amine, had absolute oral bioavailability 0.52 (0.47–0.61) in healthy subjects, directly supporting F ≥20% for a structurally related ester/amine.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C38"],
      "claim": "Solifenacin, a fused bicyclic amine with high transferability, showed absolute oral bioavailability of about 90% in healthy adults, strongly supporting high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Encainide, an aromatic amide/amine with high transfer score, had oral bioavailability of 32 ± 7% in normal subjects, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Tolfenamic acid, a chlorophenyl carboxylic acid analogue, had absolute oral bioavailability of 63.2% in healthy female volunteers, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C44"],
      "claim": "Neotame, an ester/amine-containing compound, was at least 34.3% systemically available after oral dosing, supporting F ≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Delapril, an ACE inhibitor prodrug with ester and amine functionalities, showed bioavailability >55%, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C48"],
      "claim": "Benazepril, a related ester/amine prodrug, had oral bioavailability of 28–37% in healthy volunteers, above the threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "A structurally related thienopyridine/tetrahydroisoquinoline compound had predicted human oral bioavailability of 58%, supporting high F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues have measured or predicted oral bioavailability above 20% (mostly 27–90%), and the query's ester/amine prodrug features align with these compounds. Therefore F ≥20% is supported; no affirmative evidence indicates low bioavailability.",
  "evidence_gaps": [
    "No direct experimental bioavailability measurement for the query molecule itself.",
    "Some analogue values are from disease states or predicted rather than healthy-subject absolute F.",
    "Exact metabolic first-pass behavior of the thienopyridine methyl ester in humans is not directly evidenced."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

